files.content:
.root {
  --vt-surface: #ffffff;
  --vt-surface-2: #fffafa;
  --vt-surface-deep: #1e1e1e;
  --vt-ink: #2a2a2a;
  --vt-ink-soft: #555555;
  --vt-on-deep: #ffffff;
  --vt-accent: #fb5849;
  --vt-on-accent: #ffffff;
  --vt-accent-ink: #d33a2c;
  --vt-accent-on-deep: #ff8a7a;
  --vt-line: #e8e8e8;

  width: 100%;
  max-width: 100%;
  overflow-x: clip;
  background-color: var(--vt-surface);
  color: var(--vt-ink);
  font-family: 'Noto Sans Display', 'Fira Sans', sans-serif;
  box-sizing: border-box;
}

.root *,
.root *::before,
.root *::after {
  box-sizing: border-box;
}

.root :where(a) {
  color: inherit;
  text-decoration: none;
}

.root a:focus-visible {
  outline: 2px solid var(--vt-accent);
  outline-offset: 2px;
}

.root :where(img) {
  display: block;
  max-width: 100%;
}

.root :where(h1, h2, h3, h4, p) {
  overflow-wrap: break-word;
}

.root .nav {
  position: sticky;
  top: 0;
  z-index: 50;
  background: var(--vt-surface);
  border-bottom: 1px solid var(--vt-line);
}

.root .navIn {
  max-width: 1200px;
  margin: 0 auto;
  padding: 0 24px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  min-height: 80px;
  gap: 24px;
  width: 100%;
  flex-wrap: wrap;
  min-width: 0;
}

.root .logo {
  display: inline-flex;
  align-items: center;
  flex-shrink: 0;
  max-width: 100%;
  min-width: 0;
}

.root .logo :where(img) {
  max-width: 100%;
}

.root .navLinks {
  display: flex;
  align-items: center;
  gap: 28px;
  flex-wrap: wrap;
  min-width: 0;
}

.root .navLinks a {
  font-size: 15px;
  font-weight: 600;
  letter-spacing: 0.5px;
  color: var(--vt-ink);
  transition: color 0.2s;
  white-space: nowrap;
}

.root .navLinks a:hover {
  color: var(--vt-accent);
}

.root .hero {
  display: grid;
  grid-template-columns: minmax(0, 2fr) minmax(0, 5fr);
  min-height: 640px;
  background: var(--vt-surface);
  width: 100%;
  max-width: 100%;
}

.root .heroNoMedia {
  grid-template-columns: 1fr;
}

.root .heroLeft {
  background: var(--vt-accent);
  color: var(--vt-on-accent);
  display: flex;
  flex-direction: column;
  justify-content: center;
  align-items: flex-start;
  padding: 64px 48px;
  position: relative;
  min-width: 0;
}

.root .heroKicker {
  font-size: 15px;
  text-transform: uppercase;
  letter-spacing: 3px;
  font-weight: 600;
  margin-bottom: 12px;
  color: var(--vt-on-accent);
  opacity: 0.9;
}

.root .heroTitle {
  font-family: 'Alegreya', 'Noto Sans Display', sans-serif;
  font-size: 56px;
  font-weight: 700;
  line-height: 1.1;
  color: var(--vt-on-accent);
  margin-bottom: 16px;
  max-width: 100%;
  min-width: 0;
}

.root .heroTag {
  font-size: 16px;
  line-height: 1.6;
  color: var(--vt-on-accent);
  opacity: 0.95;
  max-width: 32em;
}

.root .heroButton {
  display: inline-block;
  margin-top: 28px;
  background: var(--vt-surface);
  color: var(--vt-accent-ink);
  font-weight: 700;
  font-size: 14px;
  padding: 14px 32px;
  border-radius: 4px;
  transition: opacity 0.2s;
  max-width: 100%;
}

.root .heroButton:hover {
  opacity: 0.9;
}

.root .heroSlider {
  display: flex;
  overflow-x: auto;
  scroll-snap-type: x mandatory;
  min-width: 0;
  width: 100%;
  max-width: 100%;
  scrollbar-width: none;
}

.root .heroSlider::-webkit-scrollbar {
  display: none;
}

.root .heroSlide {
  flex: 0 0 100%;
  scroll-snap-align: start;
  min-width: 0;
}

.root .heroSlide img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  min-height: 640px;
}

.root .about {
  max-width: 1200px;
  margin: 0 auto;
  padding: 100px 24px;
  display: grid;
  grid-template-columns: minmax(0, 1fr) minmax(0, 1fr);
  gap: 60px;
  align-items: center;
}

.root .kicker {
  display: inline-block;
  font-size: 14px;
  text-transform: uppercase;
  letter-spacing: 2px;
  font-weight: 600;
  color: var(--vt-accent-ink);
  position: relative;
  padding-left: 40px;
  margin-bottom: 16px;
}

.root .kicker::before {
  content: '';
  position: absolute;
  left: 0;
  top: 50%;
  width: 30px;
  height: 1px;
  background: var(--vt-accent);
}

.root .aboutText {
  min-width: 0;
}

.root .aboutText h2 {
  font-size: 34px;
  font-weight: 800;
  line-height: 1.2;
  color: var(--vt-ink);
  margin-bottom: 24px;
}

.root .aboutText p {
  font-size: 15px;
  line-height: 1.7;
  color: var(--vt-ink-soft);
  margin-bottom: 16px;
}

.root .aboutMedia {
  position: relative;
  min-width: 0;
}

.root .aboutMain {
  border-radius: 8px;
  overflow: hidden;
}

.root .aboutMain img {
  width: 100%;
  height: 480px;
  object-fit: cover;
}

.root .aboutThumbs {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 12px;
  margin-top: -40px;
  padding: 0 20px;
}

.root .aboutThumbs img {
  width: 100%;
  height: 100px;
  object-fit: cover;
  border-radius: 6px;
  border: 4px solid var(--vt-surface);
}

.root .services {
  background: var(--vt-surface-2);
  padding: 100px 24px;
  width: 100%;
  max-width: 100%;
}

.root .sectionHead {
  max-width: 1200px;
  margin: 0 auto 60px;
}

.root .sectionHead h2 {
  font-size: 34px;
  font-weight: 800;
  color: var(--vt-ink);
  margin-top: 8px;
}

.root .menuTrack {
  max-width: 1200px;
  margin: 0 auto;
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 24px;
}

.root .menuCard {
  position: relative;
  background: var(--vt-surface);
  border-radius: 8px;
  overflow: hidden;
  box-shadow: 0 4px 14px rgba(0, 0, 0, 0.06);
  min-width: 0;
}

.root .menuImg {
  width: 100%;
  height: 220px;
  object-fit: cover;
}

.root .menuBody {
  padding: 20px;
}

.root .menuNum {
  position: absolute;
  top: 12px;
  right: 12px;
  background: var(--vt-accent);
  color: var(--vt-on-accent);
  font-size: 13px;
  font-weight: 700;
  padding: 4px 10px;
  border-radius: 4px;
}

.root .menuBody h3 {
  font-size: 19px;
  font-weight: 700;
  color: var(--vt-ink);
  margin-bottom: 8px;
}

.root .menuBody p {
  font-size: 14px;
  line-height: 1.6;
  color: var(--vt-ink-soft);
}

.root .gallery {
  max-width: 1200px;
  margin: 0 auto;
  padding: 100px 24px;
}

.root .galleryGrid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 24px;
}

.root .galleryItem {
  margin: 0;
  position: relative;
  border-radius: 8px;
  overflow: hidden;
  min-width: 0;
}

.root .galleryItem img {
  width: 100%;
  height: 280px;
  object-fit: cover;
  transition: transform 0.3s;
}

.root .galleryItem:hover img {
  transform: scale(1.03);
}

.root .galleryItem figcaption {
  position: absolute;
  left: 0;
  right: 0;
  bottom: 0;
  padding: 20px;
  background: linear-gradient(transparent, rgba(0, 0, 0, 0.7));
  color: #fff;
}

.root .galleryItem h3 {
  font-size: 18px;
  font-weight: 700;
}

.root .galleryItem p {
  font-size: 14px;
  opacity: 0.9;
}

.root .contact {
  background: var(--vt-surface-deep);
  padding: 100px 24px;
  width: 100%;
  max-width: 100%;
}

.root .contactInner {
  max-width: 1200px;
  margin: 0 auto;
  display: flex;
  flex-direction: column;
  gap: 48px;
}

.root .contactInfo {
  color: var(--vt-on-deep);
  min-width: 0;
}

.root .contactInfo .kicker {
  color: var(--vt-accent-on-deep);
}

.root .contactInfo .kicker::before {
  background: var(--vt-accent-on-deep);
}

.root .contactInfo h2 {
  font-size: 34px;
  font-weight: 800;
  color: var(--vt-on-deep);
  margin-bottom: 16px;
}

.root .contactInfo > p {
  color: var(--vt-on-deep);
  opacity: 0.85;
  line-height: 1.7;
  margin-bottom: 24px;
}

.root .contactList {
  display: grid;
  gap: 12px;
  margin-bottom: 24px;
}

.root .contactList div {
  display: flex;
  gap: 8px;
  min-width: 0;
}

.root .contactList dt {
  font-weight: 600;
  color: var(--vt-accent-on-deep);
  flex-shrink: 0;
}

.root .contactList dd {
  margin: 0;
  color: var(--vt-on-deep);
  overflow-wrap: break-word;
}

.root .contactCard {
  background: var(--vt-surface);
  border-radius: 8px;
  padding: 24px;
  min-width: 0;
  width: 100%;
  max-width: 100%;
}

.root .contactCard > * {
  width: 100%;
  max-width: 100%;
}

.root .footer {
  background: var(--vt-accent);
  padding: 40px 24px;
  width: 100%;
  max-width: 100%;
}

.root .footerInner {
  max-width: 1200px;
  margin: 0 auto;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 20px;
  flex-wrap: wrap;
}

.root .footer p {
  color: var(--vt-on-accent);
  margin: 0;
}

@media (max-width: 768px) {
  .root .navIn {
    padding: 0 16px;
    min-height: 64px;
    gap: 16px;
  }

  .root .navLinks {
    gap: 16px;
  }

  .root .hero {
    grid-template-columns: 1fr;
    min-height: auto;
  }

  .root .heroLeft {
    padding: 40px 24px;
  }

  .root .heroTitle {
    font-size: 40px;
  }

  .root .heroSlide img {
    min-height: 300px;
    height: 300px;
  }

  .root .about,
  .root .contactInner {
    grid-template-columns: 1fr;
    gap: 40px;
    padding: 60px 16px;
  }

  .root .aboutMedia {
    overflow: hidden;
  }

  .root .aboutMain img {
    height: 320px;
  }

  .root .aboutThumbs {
    margin-top: -20px;
    padding: 0 10px;
  }

  .root .aboutThumbs img {
    height: 70px;
  }

  .root .menuTrack {
    grid-template-columns: 1fr;
  }

  .root .galleryGrid {
    grid-template-columns: 1fr 1fr;
  }

  .root .contact {
    padding: 60px 16px;
  }

  .root .contactCard {
    padding: 16px;
  }
}

@media (max-width: 480px) {
  .root .navLinks a {
    font-size: 14px;
  }

  .root .heroTitle {
    font-size: 32px;
  }

  .root .galleryGrid {
    grid-template-columns: 1fr;
  }

  .root .galleryItem img {
    height: 220px;
  }
}
